#!/usr/bin/env python3
from __future__ import annotations
import argparse,base64,datetime as dt,importlib.util,json,os,py_compile,shutil,subprocess,sys
from pathlib import Path
VERSION='0.4.0'
PAYLOAD=json.loads(base64.b64decode('').decode())
MODIFIED={p:{k:base64.b64decode(v).decode('utf-8') for k,v in x.items()} for p,x in PAYLOAD['modified'].items()}
CREATED={p:base64.b64decode(v).decode('utf-8') for p,v in PAYLOAD['created'].items()}

def resolve_roots(frontend_arg=None,backend_arg=None):
 cwd=Path.cwd().resolve();fe=[];be=[]
 if frontend_arg:fe.append(Path(frontend_arg).expanduser().resolve())
 if backend_arg:be.append(Path(backend_arg).expanduser().resolve())
 fe += [cwd,cwd/'LambdaVisionSuper',cwd.parent/'LambdaVisionSuper']
 be += [cwd,cwd/'LambdaVisionSuperBackEnd',cwd.parent/'LambdaVisionSuperBackEnd']
 frontend=next((p for p in fe if (p/'src/App.tsx').exists() and (p/'src/Pages/ContourExtractorLabPage.tsx').exists()),None)
 backend=next((p for p in be if (p/'app/main.py').exists() and (p/'app/services/vision_labs/contour_extractor').exists()),None)
 if frontend is None:raise RuntimeError('Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper')
 if backend is None:raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd')
 return frontend,backend

def real_path(frontend,backend,virtual):
 if virtual.startswith('frontend/'):return frontend/virtual[len('frontend/'):]
 if virtual.startswith('backend/'):return backend/virtual[len('backend/'):]
 raise ValueError(virtual)

def mod_state(path,old,new):
 if not path.exists():return 'MISSING'
 cur=path.read_text(encoding='utf-8')
 if cur==new:return 'OK'
 if cur==old:return 'UPDATE'
 return 'CONFLICT'

def create_state(path,desired):
 if not path.exists():return 'CREATE'
 return 'OK' if path.read_text(encoding='utf-8')==desired else 'CONFLICT'

def scan(frontend,backend):
 print('='*100);print('VISION LABS V0.4.0 — CONTOUR DISCOVERY + SAMPLING DATA EXPLORATION WORKBENCH');print('='*100)
 print(f'Frontend : {frontend}');print(f'Backend  : {backend}\n');conflicts=0
 for virtual,payload in MODIFIED.items():
  state=mod_state(real_path(frontend,backend,virtual),payload['old'],payload['new']);print(f'  [{state:12}] {virtual}');conflicts += state in {'CONFLICT','MISSING'}
 for virtual,desired in CREATED.items():
  state=create_state(real_path(frontend,backend,virtual),desired);print(f'  [{state:12}] {virtual}');conflicts += state=='CONFLICT'
 print('\nRelease goals:')
 for line in [
  'FIX Contour edge_map preview 400: bool mask -> preview-safe uint8 artifact.',
  'FIX Spectral eager artifact fetch: selection != inspection/run.',
  'Contour Base Memory Filter defaults to retained cap 600.',
  'Extensible Contour Stage Registry + Fourier master-shape primitive.',
  'Large contour discovery workbench + stage guides + Fourier reconstruction.',
  'Cross/Ring sampling use configurable grids of centers.',
  'Sampling step/count is visualized as sample points on the source image.',
  'Data Layout Composer moves into its own dedicated workspace.',
  'Parameter teaching uses real image-channel previews + graphs/formulas.',
  'Spectral/Statistics become graph-first; Local FFT maps WHERE frequency energy occurs.',
  'LLM architecture/file-map/bundles/update MD regenerated for future chats/agents.',
 ]:print('  - '+line)
 if conflicts:print(f'\n[WARN] {conflicts} conflict(s). apply will stop safely.')
 return 0

def preflight(frontend,backend):
 errors=[]
 for virtual,payload in MODIFIED.items():
  state=mod_state(real_path(frontend,backend,virtual),payload['old'],payload['new'])
  if state not in {'UPDATE','OK'}:errors.append(f'{virtual}: {state}')
 for virtual,desired in CREATED.items():
  state=create_state(real_path(frontend,backend,virtual),desired)
  if state not in {'CREATE','OK'}:errors.append(f'{virtual}: {state}')
 app=(frontend/'src/App.tsx').read_text(encoding='utf-8');api=(backend/'app/api/v1/api.py').read_text(encoding='utf-8')
 if '/labs/contour-extractor' not in app or '/labs/sampling-geometry' not in app:errors.append('frontend/src/App.tsx: v0.3 routes missing')
 if 'prefix="/contour-extractor"' not in api or 'prefix="/sampling-geometry"' not in api:errors.append('backend/app/api/v1/api.py: v0.3 routers missing')
 if errors:raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errors))

def backup(frontend,backend,paths):
 stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S');root=frontend/'.lambda_updater_backups'/f'contour_sampling_v0400_{stamp}';root.mkdir(parents=True,exist_ok=True)
 for path in paths:
  if not path.exists():continue
  try:rel=path.relative_to(frontend);dest=root/'frontend'/rel
  except ValueError:rel=path.relative_to(backend);dest=root/'backend'/rel
  dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,dest)
 return root

def regenerate_context(frontend,backend):
 generator=frontend/'tools/generate_llm_context_map.py'
 if not generator.exists():print('[SKIP] Context generator not found');return
 cmd=[sys.executable,str(generator),'--frontend',str(frontend),'--backend',str(backend)]
 if '--output-dir' in generator.read_text(encoding='utf-8'):cmd += ['--output-dir',str(frontend/'docs/llm_context')]
 proc=subprocess.run(cmd,cwd=str(frontend),text=True,capture_output=True)
 if proc.returncode!=0:raise RuntimeError('Context regeneration failed:\n'+(proc.stdout+'\n'+proc.stderr).strip())
 if proc.stdout.strip():print(proc.stdout.strip())

def apply(frontend,backend):
 preflight(frontend,backend);targets=[real_path(frontend,backend,k) for k in list(MODIFIED)+list(CREATED)];root=backup(frontend,backend,targets)
 for virtual,payload in MODIFIED.items():
  path=real_path(frontend,backend,virtual)
  if path.read_text(encoding='utf-8')!=payload['new']:path.write_text(payload['new'],encoding='utf-8');print('[WRITE]',virtual)
 for virtual,desired in CREATED.items():
  path=real_path(frontend,backend,virtual);path.parent.mkdir(parents=True,exist_ok=True)
  if not path.exists() or path.read_text(encoding='utf-8')!=desired:path.write_text(desired,encoding='utf-8');print('[WRITE]',virtual)
 print('[INFO] Regenerating LLM context docs...');regenerate_context(frontend,backend);print(f'[OK] Backup: {root}');print('Run verify next.');return 0

def python_syntax(backend):
 failures=[];count=0
 for virtual in list(MODIFIED)+list(CREATED):
  if virtual.startswith('backend/') and virtual.endswith('.py'):
   count+=1;path=real_path(Path('/unused'),backend,virtual)
   try:py_compile.compile(str(path),doraise=True)
   except Exception as exc:failures.append(f'{path.relative_to(backend)}: {exc}')
 return count,failures

def ts_transpile(frontend):
 files=[real_path(frontend,Path('/unused'),v) for v in list(MODIFIED)+list(CREATED) if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]
 js='const fs=require("fs"),ts=require("typescript");let b=false;for(const f of process.argv.slice(1)){const s=fs.readFileSync(f,"utf8"),r=ts.transpileModule(s,{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}}),e=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);if(e.length){b=true;console.error("TS_ERROR",f);for(const d of e)console.error(ts.flattenDiagnosticMessageText(d.messageText,"\\n"));}}process.exit(b?1:0);'
 env=dict(os.environ);npm=subprocess.run(['npm','root','-g'],text=True,capture_output=True)
 if npm.returncode==0 and npm.stdout.strip():env['NODE_PATH']=npm.stdout.strip()+(os.pathsep+env['NODE_PATH'] if env.get('NODE_PATH') else '')
 return subprocess.run(['node','-e',js,*map(str,files)],cwd=str(frontend),env=env,text=True,capture_output=True)

def backend_smoke(backend):
 code='''import cv2, numpy as np\nfrom app.services.vision_labs.image.session import PreviewEncoder\nfrom app.services.vision_labs.image.types import ColorSpace,ImageFrame\nfrom app.services.vision_labs.contour_extractor.runtime import ContourExtractorRuntime\nfrom app.services.vision_labs.contour_extractor.stage_registry import stage_catalog\nfrom app.services.vision_labs.contour_extractor.fourier import contour_fourier_descriptor\nfrom app.services.vision_labs.sampling_geometry.operators import load_sampling_geometry_operators\nfrom app.services.vision_labs.sampling_geometry.registry import SAMPLING_OPERATOR_REGISTRY\nfrom app.services.vision_labs.core import ExecutionContext\nimg=np.zeros((260,340,3),np.uint8);cv2.rectangle(img,(20,30),(120,150),(255,255,255),3);cv2.circle(img,(240,160),65,(255,255,255),3)\nfor y in range(4,255,8):\n for x in range(5,335,11):img[y,x]=255\nframe=ImageFrame(img,color_space=ColorSpace.BGR)\nr=ContourExtractorRuntime({'source':{'early_filter':{'max_retained':80}}}).run(frame)\nassert len(r.store.contours)<=80\npayload,mime=PreviewEncoder.encode(r.sources['edge_map']);assert payload and mime=='image/png' and r.sources['edge_map'].data.dtype==np.uint8\nassert 'fourier_shape_filter' in {x['kind'] for x in stage_catalog()}\na=np.array([[0,0],[100,0],[100,50],[0,50]],np.float32);b=a*2+np.array([40,80],np.float32);assert np.linalg.norm(contour_fourier_descriptor(a,harmonics=8)-contour_fourier_descriptor(b,harmonics=8))<1e-3\nload_sampling_geometry_operators()\ndef op(i):return SAMPLING_OPERATOR_REGISTRY.get(i).operator_class()\ncross=op('sampling.spatial.housing.cross').process({'image':frame},{'center_rows':2,'center_cols':3,'margin':.1,'length':.2},ExecutionContext())['housing']\nrings=op('sampling.spatial.housing.rings').process({'image':frame},{'center_rows':2,'center_cols':2,'margin':.15,'rings':3,'inner_radius':.02,'outer_radius':.08},ExecutionContext())['housing']\nassert len(cross.metadata['centers'])==6 and len(cross.elements)==12 and len(rings.metadata['centers'])==4 and len(rings.elements)==12\nlf=op('sampling.spectral.local_fft_energy').process({'image':frame},{'channel':'gray','rows':4,'cols':5,'band_low':.1,'band_high':.5,'window':'hann','normalize':True},ExecutionContext())['energy_map'];assert lf.values.shape==(4,5) and float(lf.values.max())<=1.0001\nprint('VISION_LABS_V0400_SMOKE_OK',len(r.store.contours),len(cross.elements),len(rings.elements),lf.values.shape)'''
 return subprocess.run([sys.executable,'-c',code],cwd=str(backend),text=True,capture_output=True)

def verify(frontend,backend,skip_build=False):
 print('='*100);print('VERIFY VISION LABS V0.4.0');print('='*100);failures=0
 def read(rel,project='frontend'):
  return ((frontend if project=='frontend' else backend)/rel).read_text(encoding='utf-8')
 checks=[
 ('Contour preview converts masks to uint8','_preview_safe' in read('app/api/v1/endpoints/contour_extractor_api.py','backend') and 'np.uint8' in read('app/api/v1/endpoints/contour_extractor_api.py','backend')),
 ('Contour runtime stores preview-safe edge map','edge.astype(np.uint8)' in read('app/services/vision_labs/contour_extractor/runtime.py','backend')),
 ('Default early retained cap is 600','max_retained: int = 600' in read('app/services/vision_labs/contour_extractor/models.py','backend')),
 ('Contour Stage Registry + Fourier stage installed','fourier_shape_filter' in read('app/services/vision_labs/contour_extractor/stage_registry.py','backend')),
 ('Contour Fourier descriptor/reconstruction installed','contour_fourier_descriptor' in read('app/services/vision_labs/contour_extractor/fourier.py','backend') and 'contour_fourier_reconstruction' in read('app/services/vision_labs/contour_extractor/fourier.py','backend')),
 ('Contour discovery workbench installed','ContourStageLibrary' in read('src/Pages/ContourExtractorLabPage.tsx') and 'ContourFourierInspector' in read('src/Pages/ContourExtractorLabPage.tsx')),
 ('Contour guide includes long-term extensibility','Stage Registry' in read('src/Pages/ContourExtractorGuideModal.tsx') and 'Future Advanced Stages' in read('src/Pages/ContourExtractorGuideModal.tsx')),
 ('Spectral selection no longer eagerly fetches','selectSpectralNode' in read('src/components/VisionLabs/SamplingGeometry/useSamplingGeometryController.ts') and 'onSelect={(id,port)=>c.selectSpectralNode' in read('src/Pages/SamplingGeometryLabPage.tsx')),
 ('Spatial left panel is Sampling Unit Library','SamplingUnitLibrary' in read('src/Pages/SamplingGeometryLabPage.tsx') and 'SPATIAL WORKFLOW' not in read('src/Pages/SamplingGeometryLabPage.tsx')),
 ('Cross/Ring support center grids','center_rows' in read('app/services/vision_labs/sampling_geometry/operators/spatial.py','backend') and 'ring_grid' in read('app/services/vision_labs/sampling_geometry/operators/spatial.py','backend')),
 ('Sampling density visualization installed','_extractorPreview' in read('src/components/VisionLabs/SamplingGeometry/SamplingCanvas.tsx')),
 ('Dedicated Data Layout workspace installed','Open Data Layout Workspace' in read('src/components/VisionLabs/SamplingGeometry/DataLayoutComposer.tsx')),
 ('Real channel preview teaching installed','channelPreview' in read('src/api/samplingGeometryApi.ts') and 'onChannelPreview' in read('src/components/VisionLabs/SamplingGeometry/SamplingParameterHelpModal.tsx')),
 ('Math/formula teaching installed','μ = (1/N)' in read('src/components/VisionLabs/SamplingGeometry/SamplingParameterHelpModal.tsx') and 'σ' in read('src/components/VisionLabs/SamplingGeometry/SamplingParameterHelpModal.tsx')),
 ('Spectral inspector graph/reconstruction-first','SELECTED WAVES → INVERSE FFT' in read('src/components/VisionLabs/SamplingGeometry/ArtifactInspectorModal.tsx') and 'LineChart' in read('src/components/VisionLabs/SamplingGeometry/ArtifactInspectorModal.tsx')),
 ('Local FFT energy map installed','sampling.spectral.local_fft_energy' in read('app/services/vision_labs/sampling_geometry/operators/spectral.py','backend')),
 ('Service remove preserved','LabServiceAPI.remove' in read('src/Pages/LabView.tsx') and '@router.delete("/{service_id}")' in read('app/api/v1/endpoints/lab_service_api.py','backend')),
 ('v0.4 system update note installed',(frontend/'docs/llm_context/updates/v0400_contour_sampling_workbench.md').exists()),
 ('Context generator knows new deep files','ContourFourierInspector.tsx' in read('tools/generate_llm_context_map.py') and 'SamplingUnitLibrary.tsx' in read('tools/generate_llm_context_map.py'))]
 for label,ok in checks:print(f'[{"OK" if ok else "FAIL"}] {label}');failures+=0 if ok else 1
 count,issues=python_syntax(backend)
 if issues:print('[FAIL] Python syntax');[print('  -',x) for x in issues];failures+=len(issues)
 else:print(f'[OK] Python syntax ({count} changed/new backend files)')
 smoke=backend_smoke(backend)
 if smoke.returncode==0:print('[OK] Backend Contour/Sampling smoke');print(smoke.stdout.strip())
 else:print('[FAIL] Backend smoke');print((smoke.stdout+'\n'+smoke.stderr).strip());failures+=1
 tests=['tests/vision_labs/contour_extractor/test_contour_extractor_v0100.py','tests/vision_labs/contour_extractor/test_contour_extractor_v0200.py','tests/vision_labs/sampling_geometry/test_sampling_lab_v0300.py','tests/vision_labs/sampling_geometry/test_sampling_lab_v0400.py','tests/vision_labs/sampling_geometry/test_sampling_geometry_lab_v0200.py']
 if importlib.util.find_spec('pytest') is None:print('[SKIP] pytest unavailable')
 else:
  proc=subprocess.run([sys.executable,'-m','pytest','-q',*tests],cwd=str(backend),text=True,capture_output=True)
  if proc.returncode==0:print('[OK] Backend regression tests');print(proc.stdout.strip())
  else:print('[FAIL] Backend regression tests');print((proc.stdout+'\n'+proc.stderr).strip());failures+=1
 ts=ts_transpile(frontend);t=(ts.stdout+'\n'+ts.stderr).strip()
 if ts.returncode==0:print('[OK] TypeScript syntax/transpile')
 elif 'Cannot find module' in t or 'MODULE_NOT_FOUND' in t:print('[SKIP] TypeScript module unavailable to Node')
 else:print('[FAIL] TypeScript syntax/transpile');print(t);failures+=1
 if not skip_build and (frontend/'package.json').exists() and (frontend/'node_modules').exists():
  proc=subprocess.run(['npm','run','build'],cwd=str(frontend));print('[OK] Frontend npm build' if proc.returncode==0 else '[FAIL] Frontend npm build');failures+=proc.returncode!=0
 else:print('[SKIP] Frontend npm build')
 try:
  regenerate_context(frontend,backend);arch=frontend/'docs/llm_context/SYSTEM_ARCHITECTURE.md';bundles=frontend/'docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md';ok=arch.exists() and bundles.exists() and 'Contour Extractor LAB' in arch.read_text(encoding='utf-8') and 'Sampling LAB' in arch.read_text(encoding='utf-8') and 'ContourFourierInspector.tsx' in bundles.read_text(encoding='utf-8');print(f'[{"OK" if ok else "FAIL"}] Regenerated LLM architecture/context bundles');failures+=0 if ok else 1
 except Exception as exc:print('[FAIL] Context regeneration:',exc);failures+=1
 if failures:print(f'[FAIL] v0.4.0 verification finished with {failures} issue(s).');return 1
 print('[OK] Contour Discovery / Sampling Workbench v0.4.0 verified.');return 0

def main():
 p=argparse.ArgumentParser();p.add_argument('command',choices=['scan','apply','verify']);p.add_argument('--frontend');p.add_argument('--backend');p.add_argument('--skip-build',action='store_true');a=p.parse_args()
 try:
  f,b=resolve_roots(a.frontend,a.backend)
  if a.command=='scan':return scan(f,b)
  if a.command=='apply':return apply(f,b)
  return verify(f,b,a.skip_build)
 except Exception as exc:print('[ERROR]',exc);return 2
if __name__=='__main__':raise SystemExit(main())
